"use client";

import { FormEvent, ReactNode, useEffect, useRef, useState } from "react";

// All application data and auth now live behind the standalone Express + MongoDB
// API (see server/). Every relative "/api/..." call made anywhere below is
// transparently redirected there with the session cookie attached, so none of
// the component code below needs to know the API moved off this origin.
if (typeof window !== "undefined") {
  const API_BASE = (import.meta as any).env?.VITE_API_BASE_URL || "http://localhost:5000";
  const nativeFetch = window.fetch.bind(window);
  window.fetch = (input: RequestInfo | URL, init?: RequestInit) => {
    const url = typeof input === "string" ? input : input instanceof URL ? input.toString() : (input as Request).url;
    if (url.startsWith("/api/")) {
      return nativeFetch(`${API_BASE}${url}`, { ...init, credentials: "include" });
    }
    return nativeFetch(input as RequestInfo, init);
  };
}

