function downloadBlob(filename: string, content: BlobPart, type: string) {
  const href = URL.createObjectURL(new Blob([content], { type }));
  const link = document.createElement("a");
  link.href = href;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(href);
}

function downloadCsv(filename: string, rows: (string | number)[][]) {
  const csv = rows.map((row) => row.map((value) => `"${String(value ?? "").replace(/"/g, '""')}"`).join(",")).join("\n");
  downloadBlob(filename, `\uFEFF${csv}`, "text/csv;charset=utf-8");
}

function downloadPdf(filename: string, title: string, lines: string[]) {
  const clean = (value: string) => value.replace(/→/g, "to").replace(/·/g, "-").normalize("NFKD").replace(/[^\x20-\x7E]/g, "");
  const escapePdf = (value: string) => clean(value).replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
  const wrap = (value: string, width = 82) => { const words = clean(value).split(/\s+/); const output: string[] = []; let line = ""; words.forEach((word) => { if (`${line} ${word}`.trim().length > width) { if (line) output.push(line); line = word; } else line = `${line} ${word}`.trim(); }); if (line) output.push(line); return output; };
  const bodyLines = lines.flatMap((line) => line ? wrap(line) : [""]).slice(0, 44);
  const commands = [`BT /F1 19 Tf 50 792 Td (${escapePdf(title)}) Tj ET`];
  bodyLines.forEach((line, index) => commands.push(`BT /F1 ${index < 2 ? 11 : 10} Tf 50 ${760 - index * 16} Td (${escapePdf(line)}) Tj ET`));
  const stream = commands.join("\n");
  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",
    `<< /Length ${new TextEncoder().encode(stream).length} >>\nstream\n${stream}\nendstream`,
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
  ];
  let pdf = "%PDF-1.4\n";
  const offsets = [0];
  objects.forEach((object, index) => { offsets.push(new TextEncoder().encode(pdf).length); pdf += `${index + 1} 0 obj\n${object}\nendobj\n`; });
  const xref = new TextEncoder().encode(pdf).length;
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.slice(1).map((offset) => `${String(offset).padStart(10, "0")} 00000 n `).join("\n")}\ntrailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  downloadBlob(filename, new TextEncoder().encode(pdf), "application/pdf");
}

