const entityCollections = ["tickets", "cargo", "visas", "expenses", "suppliers", "clients", "closes", "rates", "startingBalances", "paymentMethods", "branchPaymentMethods"] as const;
type EntityCollection = typeof entityCollections[number];
function changedEntity(current: AgencyData, next: AgencyData): { collection: EntityCollection; record?: Record<string, unknown>; deletedId?: string; created: boolean } | null {
  const changed = entityCollections.filter((key) => current[key] !== next[key]);
  const nonEntityChanged = current.agencyName !== next.agencyName || current.users !== next.users;
  if (nonEntityChanged || changed.length !== 1) return null;
  const collection = changed[0];
  const before = current[collection] as Array<Record<string, unknown>>;
  const after = next[collection] as Array<Record<string, unknown>>;
  const beforeIds = new Set(before.map((item) => String(item.id || "")));
  const afterIds = new Set(after.map((item) => String(item.id || "")));
  const added = after.filter((item) => !beforeIds.has(String(item.id || "")));
  const removed = before.filter((item) => !afterIds.has(String(item.id || "")));
  const updated = after.filter((item) => {
    const prior = before.find((candidate) => candidate.id === item.id);
    return prior && prior !== item;
  });
  if (added.length === 1 && removed.length === 0 && updated.length === 0) return { collection, record: added[0], created: true };
  if (added.length === 0 && removed.length === 0 && updated.length === 1) return { collection, record: updated[0], created: false };
  if (added.length === 0 && removed.length === 1 && updated.length === 0) return { collection, deletedId: String(removed[0].id), created: false };
  return null;
}

