const [data, setData] = useState<AgencyData>(emptyData); const dataRef = useRef<AgencyData>(emptyData); const saveQueueRef = useRef<Promise<void>>(Promise.resolve()); const [ready, setReady] = useState(false); const [user, setUser] = useState<User | null>(null); const [setupRequired, setSetupRequired] = useState(false); const [portalPath, setPortalPath] = useState("/"); const [loadError, setLoadError] = useState(""); const [page, setPage] = useState<Page>("overview"); const [mobileNav, setMobileNav] = useState(false); const [toast, setToast] = useState("");
  const applyData = (source: Partial<AgencyData>) => { const next = syncClients({ ...emptyData, ...source }); dataRef.current = next; setData(next); };
  const loadWorkspace = async (signedIn: User) => { const response = await fetch("/api/data", { cache: "no-store" }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error || "Could not load agency data."); applyData(payload.data || {}); setLoadError(""); setUser(signedIn); };
  useEffect(() => { let active = true; const load = async () => {
    const path = window.location.pathname;
    setPortalPath(path);
    if (path === "/") { setReady(true); return; }
    try {
      const statusResponse = await fetch("/api/auth/status", { cache: "no-store" });
      const status = await statusResponse.json();
      if (!statusResponse.ok) throw new Error(status.error || "Secure storage is unavailable.");
      if (!active) return;
      setSetupRequired(Boolean(status.setupRequired));
      if (status.setupRequired) return;
      const meResponse = await fetch("/api/auth/me", { cache: "no-store" });
      if (meResponse.status === 401) return;
      const me = await meResponse.json();
      if (!meResponse.ok) throw new Error(me.error || "The current session could not be checked.");
      const sessionUser = me.user as User;
      if (path === "/admin" && sessionUser.role !== "owner") {
        await fetch("/api/auth/logout", { method: "POST" });
        return;
      }
      if (path.startsWith("/portal/")) {
        const token = path.split("/").filter(Boolean)[1] || "";
        const linkResponse = await fetch(`/api/auth/link?token=${encodeURIComponent(token)}`, { cache: "no-store" });
        const link = await linkResponse.json();
        if (!linkResponse.ok) throw new Error(link.error || "This staff access link is unavailable.");
        if (String(link.user.username).toLowerCase() !== sessionUser.username.toLowerCase()) {
          await fetch("/api/auth/logout", { method: "POST" });
          return;
        }
      }
      const dataResponse = await fetch("/api/data", { cache: "no-store" });
      const payload = await dataResponse.json();
      if (!dataResponse.ok) throw new Error(payload.error || "Could not load agency data.");
      if (!active) return;
      applyData(payload.data || {});
      setUser(sessionUser);
    } catch (error) { if (active) setLoadError(error instanceof Error ? error.message : "Could not open the secure workspace."); }
    finally { if (active) setReady(true); }
  }; void load(); return () => { active = false; }; }, []);
  useEffect(() => { if (!toast) return; const id = setTimeout(() => setToast(""), 2800); return () => clearTimeout(id); }, [toast]);
const save = (updater: (current: AgencyData) => AgencyData, action?: { entity: string; detail: string }) => { if (!user) return; saveQueueRef.current = saveQueueRef.current.catch(() => undefined).then(async () => { const current = dataRef.current; const rawNext = updater(current); const entityChange = changedEntity(current, rawNext); const snapshot = syncClients(rawNext); const response = entityChange ? await fetch(entityChange.deletedId ? `/api/entities/${entityChange.collection}/${encodeURIComponent(entityChange.deletedId)}` : `/api/entities/${entityChange.collection}${entityChange.created ? "" : `/${encodeURIComponent(String(entityChange.record?.id || ""))}`}`, { method: entityChange.deletedId ? "DELETE" : entityChange.created ? "POST" : "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ record: entityChange.record, action }) }) : await fetch("/api/data", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ data: snapshot }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error || "Changes could not be saved."); if (payload.data) applyData(payload.data); }).catch(async(error) => { try { const response=await fetch("/api/data",{cache:"no-store"}); const payload=await response.json(); if(response.ok&&payload.data)applyData(payload.data); } catch {} setToast(error instanceof Error ? error.message : "Changes could not be saved."); }); };
  const notify = (message: string) => setToast(message);
  if (!ready) return <main className="loading-screen"><BrandMark/><p>Preparing your agency workspace…</p></main>;
  if (portalPath === "/") return <Landing />;
  if (loadError && !user) return <AuthMessage title="Access unavailable" detail={loadError} />;
